function label(value) {
  if (typeof value !== 'string') return value;
  if (Object.hasOwn(labels,value)) return labels[value];
  const trimmed=value.trim();
  if(Object.hasOwn(labels,trimmed))return value.slice(0,value.indexOf(trimmed))+labels[trimmed]+value.slice(value.indexOf(trimmed)+trimmed.length);
  const split=value.indexOf('/');
  if(split>0 && /^\d{1,2}:\d{2}$/.test(value.slice(split+1)) && Object.hasOwn(labels,value.slice(0,split)))return labels[value.slice(0,split)]+value.slice(split);
  if(value.endsWith('相关') && Object.hasOwn(labels,value.slice(0,-2)))return labels[value.slice(0,-2)];
  return value;
}
const weekdays={日:'Sun',天:'Sun',一:'Mon',二:'Tue',三:'Wed',四:'Thu',五:'Fri',六:'Sat'};
const fullWeekdays={日:'Sunday',天:'Sunday',一:'Monday',二:'Tuesday',三:'Wednesday',四:'Thursday',五:'Friday',六:'Saturday'};
const holidays={
  元旦:"New Year's Day",情人节:"Valentine's Day",妇女节:"Women's Day",植树节:'Arbor Day',愚人节:"April Fools' Day",劳动节:'Labour Day',青年节:'Youth Day',儿童节:"Children's Day",建党节:'CPC Founding Day',七七事变:'July 7 Incident',建军节:'Army Day',日本投降日:'Japan Surrender Day',胜利日:'Victory Day',教师节:"Teachers' Day",国庆节:'National Day',万圣夜:'Halloween',国家公祭日:'National Memorial Day',平安夜:'Christmas Eve',圣诞节:'Christmas',
  除夕:"Lunar New Year's Eve",春节:'Lunar New Year',元宵节:'Lantern Festival',端午节:'Dragon Boat Festival',七夕节:'Qixi Festival',中元节:'Ghost Festival',中秋节:'Mid-Autumn Festival',重阳节:'Double Ninth Festival',腊八节:'Laba Festival',
  小寒:'Minor Cold',大寒:'Major Cold',立春:'Start of Spring',雨水:'Rain Water',惊蛰:'Awakening of Insects',春分:'Spring Equinox',清明:'Qingming',清明节:'Qingming Festival',谷雨:'Grain Rain',立夏:'Start of Summer',小满:'Grain Buds',芒种:'Grain in Ear',夏至:'Summer Solstice',小暑:'Minor Heat',大暑:'Major Heat',立秋:'Start of Autumn',处暑:'End of Heat',白露:'White Dew',秋分:'Autumn Equinox',寒露:'Cold Dew',霜降:'Frost Descent',立冬:'Start of Winter',小雪:'Minor Snow',大雪:'Major Snow',冬至:'Winter Solstice',休:'Off',班:'Work'
};
const digits={'〇':0,'零':0,'一':1,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9};
function number(text){
  if(/^\d+$/.test(text))return Number(text);
  if(text==='正')return 1;if(text==='冬')return 11;if(text==='腊')return 12;
  text=text.replace(/^初/,'').replace(/^廿/,'二十').replace(/^卅/,'三十');
  if(text.includes('十')){const [t,u]=text.split('十');return (t?digits[t]:1)*10+(u?digits[u]:0);}
  if([...text].every(x=>x in digits))return Number([...text].map(x=>digits[x]).join(''));
  return text;
}
function ordinal(n){n=Number(n);const r=n%100;return n+(r>=11&&r<=13?'th':({1:'st',2:'nd',3:'rd'}[n%10]||'th'));}
function textCalendar(value){
  // Birthday names are user content. Preserve the captured name verbatim.
  let m=value.match(/^(.*)的(\d+)岁生日$/);if(m)return m[1]+"'s "+ordinal(m[2])+' birthday';
  m=value.match(/^(.*)的生日$/);if(m)return m[1]+"'s birthday";
  if(Object.hasOwn(holidays,value))return holidays[value];
  if(/^星期[日天一二三四五六]$/.test(value))return fullWeekdays[value.at(-1)];
  if(/^周[日天一二三四五六]$/.test(value))return weekdays[value.at(-1)];
  if(/^[初廿卅一二三四五六七八九十零〇]+$/.test(value))return 'L'+number(value);
  let s=value;
  s=s.replace(/([〇零一二三四五六七八九]{4})年/g,(_,y)=>number(y)+' ');
  s=s.replace(/(\d{4})年(\d{1,2})月(\d{1,2})日/g,(_,y,m,d)=>y+'-'+m.padStart(2,'0')+'-'+d.padStart(2,'0'));
  s=s.replace(/(\d{1,2})月(\d{1,2})日/g,(_,m,d)=>m+'/'+d);
  s=s.replace(/闰([正冬腊一二三四五六七八九十]+)月([初廿卅一二三四五六七八九十]*)/g,(_,m,d)=>'Leap L'+number(m)+(d?'/'+number(d):''));
  s=s.replace(/([正冬腊一二三四五六七八九十]+)月([初廿卅一二三四五六七八九十]*)/g,(_,m,d)=>'L'+number(m)+(d?'/'+number(d):''));
  s=s.replace(/农历([初廿卅一二三四五六七八九十]+)/g,(_,d)=>'Lunar '+number(d));
  s=s.replace(/星期([日天一二三四五六])/g,(_,d)=>fullWeekdays[d]);
  s=s.replace(/周([日天一二三四五六])/g,(_,d)=>weekdays[d]);
  s=s.replace(/第([一二三四五六七八九十\d]+)个/g,(_,n)=>ordinal(number(n))+' ');
  s=s.replace(/日程将(.+)重复/g,'Repeats $1');
  s=s.replace(/每(\d+)(天|日|周|月|年)/g,(_,n,u)=>'Every '+n+' '+({天:'days',日:'days',周:'weeks',月:'months',年:'years'}[u]));
  const terms={'每年':'Yearly','每月':'Monthly','每周':'Weekly','每天':'Daily','每个工作日':'Weekdays','工作日':'Weekdays','农历':'Lunar ','今天':'Today','明天':'Tomorrow','昨天':'Yesterday','开始':'Start','结束':'End','全天':'All day','无提醒':'No reminder','永不':'Never','次数':'Occurrences','重复':'Repeat','准时':'At start time','当天':'On the day'};
  for(const [from,to]of Object.entries(terms))s=s.split(from).join(to);
  s=s.replace(/(\d+)(分钟|小时|天|周|年)(前|后)/g,(_,n,u,d)=>n+' '+({分钟:'min',小时:'hour',天:'day',周:'week',年:'year'}[u])+(n!=='1'&&u!=='分钟'?'s':'')+' '+(d==='前'?'before':'after'));
  s=s.replace(/(\d+)周年/g,(_,n)=>ordinal(n)+' anniversary');
  s=s.replace(/(\d{4})年/g,'$1').replace(/(\d+)日/g,'day $1');
  s=s.replace(/至/g,' to ').replace(/、/g,', ').replace(/，/g,', ').replace(/：/g,': ').replace(/（/g,' (').replace(/）/g,')');
  if(Object.hasOwn(holidays,s))return holidays[s];
  return label(s);
}
function calendarLabel(value){
  if(typeof value!=='string')return value;
  // Preserve tags and their attributes in rich-text calendar subheadings.
  return value.split(/(<[^>]*>)/g).map(part=>part.startsWith('<')?part:textCalendar(part)).join('');
}
function weekday(value){return typeof value==='string'?(weekdays[value]||calendarLabel(value)):value;}
function albumFolder(item){return item.changeable===false&&[1,2,3,5,6,7,8].includes(Number(item.navType))?label(item.folderName):item.folderName;}
module.exports={label,calendarLabel,weekday,albumFolder};
